export const cars: Resource = {};
export const raceCars: Resource = {};

export const carsGroups: ResourceGroups = manufacturers.map((manufacturer) => ({
  name: manufacturer.name,
  options: [],
}));
export const raceCarsGroups: ResourceGroups = manufacturers.map(
  (manufacturer) => ({
    name: manufacturer.name,
    options: [],
  }),
);

export const raceCarsOrder: number[] = [];

carList.forEach((car) => {
  cars[car.index] = car.name;
  carsGroups[car.manufacturer].options.push(car.index);

  raceCars[car.raceIndex] = car.name;
  raceCarsGroups[car.manufacturer].options.push(car.raceIndex);
  raceCarsOrder.push(car.raceIndex);
});

